mplate-columns:1.05fr .95fr;gap:clamp(2rem,5vw,4.5rem);align-items:start}.dot-prog{position:relative;padding:clamp(1.6rem,4vw,2.4rem);background:#fff;border-radius:6px;box-shadow:0 30px 60px -44px rgba(28,42,34,.6);text-align:center}.dot-prog::before{content:"";position:absolute;inset:10px;border:1px solid rgba(201,162,75,.6);border-radius:3px;pointer-events:none}.dot-prog h3{font-family:Italiana,serif;font-weight:400;font-size:1.9rem;color:var(--vert);margin-bottom:1.4rem;text-transform:none}.dot-prog ol{display:grid;gap:1.2rem;counter-reset:pr}.dot-prog li{counter-increment:pr}.dot-prog li::before{content:counter(pr,upper-roman);display:block;font-family:Italiana,serif;font-size:1.6rem;color:var(--or);line-height:1}.dot-prog b{display:block;font-family:Lora,serif;font-weight:600;font-size:1.08rem;color:var(--ink);margin:.2rem 0}.dot-prog span{font-size:.94rem;color:var(--soft);font-style:italic}/* Inventaire */.dot-inv{padding:clamp(4rem,8vw,6.5rem) 0;background:var(--creme)}.dot-inv-g{display:grid;grid-template-columns:.95fr 1.05fr;gap:clamp(2rem,5vw,4.5rem);align-items:start}.dot-list{padding:clamp(1.6rem,4vw,2.4rem);background:#fff;border-radius:6px;box-shadow:0 30px 60px -44px rgba(28,42,34,.6);background-image:repeating-linear-gradient(180deg,transparent 0 41px,rgba(29,74,55,.1) 41px 42px);background-position:0 3.6rem}.dot-list h3{font-family:"Pinyon Script",cursive;font-weight:400;font-size:2.4rem;color:var(--bord);margin-bottom:.6rem;text-transform:none}.dot-list li{display:flex;align-items:center;gap:1rem;height:42px;font-size:1.05rem;color:var(--ink)}.dot-list li i{flex:none;width:22px;height:22px;border-radius:6px;outline:2px solid var(--vert);outline-offset:-2px;display:grid;place-items:center;font-style:normal;font-size:.9rem;font-weight:700;color:#fff;transition:background .35s ease var(--dl,0ms)}.dot-list li i::after{content:"✓";opacity:0;transition:opacity .35s ease var(--dl,0ms)}.dot-list.on li i,.dot:not(.dot-js) .dot-list li i{background:var(--vert)}.dot-list.on li i::after,.dot:not(.dot-js) .dot-list li i::after{opacity:1}.dot-list .dot-nb{margin-top:1rem;font-style:italic;font-size:.92rem!important}.dot-inv .dot-ph{margin-top:1.6rem;aspect-ratio:4/3;border-radius:6px;box-shadow:0 30px 60px -40px rgba(28,42,34,.7)}/* Plan des places */.dot-pl{padding:clamp(4rem,8vw,6.5rem) 0}.dot-pl-g{display:grid;grid-template-columns:1.05fr .95fr;gap:clamp(2rem,5vw,4.5rem);align-items:start}.dot-plan{padding:1.6rem;border-radius:6px;background:var(--vert);color:#f4ead2;box-shadow:0 30px 60px -40px rgba(28,42,34,.8)}.dot-plan h3{font-family:Italiana,serif;font-weight:400;font-size:1.7rem;color:#fff;text-align:center;margin-bottom:1.2rem;text-transform:none}.dot-room{display:grid;grid-template-columns:1fr 64px 1fr;gap:.6rem;align-items:stretch}.dot-side{padding:1rem .8rem;border-radius:6px;background:rgba(255,255,255,.07);text-align:center}.dot-side b{display:block;font-size:.72rem;letter-spacing:.2em;text-transform:uppercase;color:var(--or);margin-bottom:.8rem}.dot-seats{display:grid;grid-template-columns:repeat(4,1fr);gap:.45rem;justify-items:center}.dot-seats i{width:18px;height:18px;border-radius:50%;background:rgba(244,234,210,.85)}.dot-side:last-child .dot-seats i{background:rgba(201,162,75,.9)}.dot-allee{border-radius:6px;background:repeating-linear-gradient(180deg,rgba(255,255,255,.12) 0 10px,transparent 10px 20px);display:grid;place-items:center}.dot-allee span{writing-mode:vertical-rl;transform:rotate(180deg);font-size:.66rem;letter-spacing:.24em;text-transform:uppercase;color:rgba(244,234,210,.8)}.dot-porte{margin-top:.8rem;text-align:center;font-size:.86rem;color:rgba(244,234,210,.85)}.dot-ok{margin-top:1.2rem;display:grid;grid-template-columns:1fr 1fr;gap:.8rem}.dot-ok div{padding:1.1rem 1.2rem;border-radius:6px;background:#fff;box-shadow:0 20px 40px -32px rgba(28,42,34,.6)}.dot-ok b{display:block;font-family:Italiana,serif;font-size:1.3rem;color:var(--vert);margin-bottom:.4rem}.dot-ok li{font-size:.92rem;color:var(--soft);line-height:1.55;padding-left:1.3rem;position:relative}.dot-ok li+li{margin-top:.35rem}.dot-ok li::before{content:"✓";position:absolute;left:0;color:var(--vert)}.dot-ok div+div li::before{content:"✕";color:var(--bord)}.dot-pl .dot-ph{margin-top:1.4rem;aspect-ratio:16/10;border-radius:6px}/* Réponse (RSVP) */.dot-rsvp{padding:clamp(4rem,8vw,6.5rem) 0;background:radial-gradient(70% 60% at 50% 100%,#245a44,var(--vert))}.dot-rsvp .dot-card{max-width:980px;text-align:left}.dot-rsvp .dot-card h2{text-align:center}.dot-rsvp .dot-k{text-align:center}.dot-rsvp ul{display:grid;gap:.7rem;margin-top:1.4rem}.dot-rsvp li{display:grid;grid-template-columns:11rem 1fr;gap:1rem;padding:.9rem 1.1rem;border-radius:4px;background:var(--creme);font-size:.98rem;line-height:1.65;color:var(--soft)}.dot-rsvp li strong{font-family:Italiana,serif;font-weight:400;font-size:1.25rem;color:var(--bord)}.dot-act{margin-top:1.8rem;text-align:center}.dot-act p{font-style:italic;margin-bottom:1rem}.dot-btn{padding:1rem 1.8rem;border-radius:999px;background:var(--bord);color:#fff!important;letter-spacing:.04em}@media (max-width:900px){.dot-der-g,.dot-inv-g,.dot-pl-g{grid-template-columns:1fr}}@media (max-width:640px){.dot-ok{grid-template-columns:1fr}.dot-rsvp li{grid-template-columns:1fr;gap:.1rem}.dot-sceau{width:96px;height:96px}.dot-seats{grid-template-columns:repeat(3,1fr)}.dot-room{grid-template-columns:1fr 40px 1fr}}</style><!-- La dot et le mariage, faire-part et déroulé : mise en page propre à cette page (préfixe dot). Textes et photos d'origine repris à l'identique et dans le même ordre, pour que les modifications de « Textes et images » continuent de s'appliquer. -->
<section class="dot-fp"><div class="dot-in"><div class="dot-card dot-rv"><span class="dot-k">Au Bénin, on se marie trois fois</span><span class="sc">Faire-part</span><div class="dot-lead"><p>Au Bénin, on ne se marie pas une fois mais trois : à la coutume, à la mairie, au culte. La première est celle qui engage les familles, et c'est souvent la plus longue.</p></div>
<div class="dot-sceaux"><div class="dot-sceau"><div><span>I</span><b>La coutume</b></div></div><div class="dot-sceau"><div><span>II</span><b>La mairie</b></div></div><div class="dot-sceau"><div><span>III</span><b>Le culte</b></div></div></div></div></div></section>

<section class="dot-der"><div class="dot-in"><div class="dot-der-g"><div class="dot-txt dot-rv"><span class="dot-k">Premier temps · Les familles</span><h2>Deux familles avant deux personnes</h2><div style="margin-top:1.4rem"><p>Dans le sud du pays, le mariage coutumier est d'abord une négociation entre deux lignages. La séquence, avec des variantes selon qu'on est en milieu fon, goun, aja ou yoruba, suit une logique constante. La famille du prétendant se manifeste d'abord par un intermédiaire, un aîné ou un ami de la maison. Chaque camp se renseigne alors sur l'autre.</p><p>Vient ensuite la demande officielle, faite au domicile de la famille de la jeune femme. Les deux groupes ne se parlent pas directement : chacun a son porte-parole, et les échanges passent par eux, souvent avec humour et proverbes. Le consentement de la future épouse est sollicité publiquement, devant l'assemblée.</p></div></div>
<div class="dot-prog dot-rv" style="--dl:150ms"><h3>Ordre de la cérémonie</h3><ol><li><b>L'intermédiaire</b><span>un aîné ou un ami de la maison se manifeste</span></li><li><b>L'enquête</b><span>chaque camp se renseigne sur l'autre</span></li><li><b>La demande officielle</b><span>chez la famille de la jeune femme, par les porte-parole</span></li><li><b>Le consentement</b><span>demandé publiquement, devant l'assemblée</span></li></ol></div></div></div></section>

<section class="dot-inv"><div class="dot-in"><div class="dot-inv-g"><div class="dot-rv"><div class="dot-list" data-on><h3>Ce qui est présenté</h3><ul><li style="--dl:0ms"><i aria-hidden="true"></i>Boissons</li><li style="--dl:150ms"><i aria-hidden="true"></i>Noix de cola</li><li style="--dl:300ms"><i aria-hidden="true"></i>Pagnes</li><li style="--dl:450ms"><i aria-hidden="true"></i>Sel et huile</li><li style="--dl:600ms"><i aria-hidden="true"></i>Produits vivriers</li><li style="--dl:750ms"><i aria-hidden="true"></i>Une somme d'argent</li></ul><p class="dot-nb">Chaque élément est annoncé à voix haute, vérifié, puis accepté ou renvoyé pour complément. La liste varie d'une famille à l'autre.</p></div>
<div class="dot-ph" data-big>@endverbatim<x-media.figure
    src="/assets/img/mariage-640x480.webp"
    alt="Un mariage traditionnel au Bénin"
    loading="native"
    caption="Un mariage traditionnel au Bénin"
    author="Wikimedia Commons"
/>@verbatim</div><div class="dot-ph" data-big style="aspect-ratio:16/10">@endverbatim<x-media.figure
    src="/assets/img/marche-rue-640x480.webp"
    alt="Un marché de rue au Bénin"
    loading="native"
    caption="Un marché de rue"
